function resetAccountState(auth){cancelVoice(true);state.chooseRoom=false;state.auth=auth;state.ready=auth.mode==='cloud'&&!auth.authenticated;state.project=null;state.projects=[];state.selected.clear();state.candidateFilter=null;state.job=null;state.visual=null;state.view='workspace';state.canvasMode='original';assistantOpen=false;loadDrafts();renderRail();}
async function loadProjects(){const result=await api('/api/projects');state.projects=result.projects||[];if(state.projects.length){let activeId;try{activeId=sessionStorage.getItem(scopedKey('activeProject'))||(accountScope()==='local'?sessionStorage.getItem('homely.activeProject'):null);}catch{}const selected=state.projects.find(p=>p.id===activeId)||state.projects[0];state.project=(await api('/api/projects/'+selected.id)).project;visualHistory.delete(historyKey());}state.ready=true;}
$('#auth-account').onclick=()=>{$('#detail-content').innerHTML=`<div class="eyebrow">PRIVATE CLOUD WORKSPACE</div><h2>Your account</h2><p>${esc(state.auth?.user?.email||'Signed in')}</p><p>Signing out hides this account’s projects and conversation. Drafts stay isolated to this account in this browser tab. No password is stored.</p><button class="button primary" id="auth-sign-out">Sign out</button>`;openDetail();$('#auth-sign-out').onclick=e=>action(e.currentTarget,async()=>{await api('/api/auth/sign-out','POST',{});$('#detail-dialog').close();resetAccountState({mode:'cloud',authenticated:false,user:null});render();notify('Signed out. Your private workspace is hidden.');});};
async function init(){render();try{const auth=await api('/api/auth/session');resetAccountState(auth);render();state.availableFeatures=await api('/api/capabilities').catch(()=>({passwordRecovery:false,confirmationResend:false,priceWatch:false}));const health=await api('/api/health');state.configured=health.openaiConfigured;$('#connection').textContent=auth.mode==='cloud'?(auth.authenticated?'●  Cloud workspace connected':'Private cloud · sign in'):(state.configured?'●  Local studio connected':'●  Studio · provider not configured');if(auth.mode==='cloud'&&!auth.authenticated)return;await loadProjects();render();}catch(e){$('#connection').textContent='Connection needs attention';notify('Workspace could not connect: '+e.message+' Reload to retry.',true);}}
// Typed and push-to-talk input share one project/version-aware intent endpoint.
const conversations = {};
let assistantOpen = false;
let voice = {phase:'idle', token:0, recorder:null, stream:null, timer:null, abort:null, error:'', seconds:0};
function conversation(){const key=accountScope()+':'+draftKey();if(!conversations[key]){let draft='';try{draft=sessionStorage.getItem(scopedKey('assistantDraft.'+draftKey()))||'';}catch{}conversations[key]={draft,messages:[],proposal:null,busy:false,error:''};}return conversations[key];}
function storeAssistantDraft(value){const c=conversation();c.draft=value;try{sessionStorage.setItem(scopedKey('assistantDraft.'+draftKey()),value);}catch{}}
function openAssistant(){assistantOpen=true;renderAssistant();$('#assistant-panel').scrollIntoView({behavior:'smooth',block:'nearest'});$('#assistant-message')?.focus();}
function renderAssistant(){if(!selectedRoom()&&state.view==='workspace'){const voiceActive=['consent','requesting','recording','transcribing'].includes(voice.phase);$('#assistant-panel').hidden=!voiceActive;const composer=$('#room-name-form');if(composer)composer.hidden=voiceActive;if(voice.phase==='review'&&$('#room-name')){$('#room-name').value=conversation().draft;$('#room-name').focus();}if(voice.error&&!voiceActive)notify(voice.error,true);}if(state.view==='workspace')assistantOpen=true;$('#assistant-panel').dataset.voicePhase=voice.phase;const c=conversation(),recording=['requesting','recording','transcribing'].includes(voice.phase);$('#assistant-panel').innerHTML=`<button id="assistant-toggle" class="assistant-toggle" aria-expanded="${assistantOpen}"><span class="assistant-orb"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v3M9 21h6"/></svg></span><span><strong>${voice.phase==='recording'?'Listening…':voice.phase==='transcribing'?'Transcribing…':'Ready when you are'}</strong><small>${assistantOpen?'One conversation, connected to your project.':'Microphone off'}</small></span><span class="room-voice-prompt">${esc(c.draft||'Tell me what you have in mind for this room.')}</span><span class="assistant-chevron">${assistantOpen?'−':'+'}</span></button>${!assistantOpen?'<div class="assistant-idle-actions"><button type="button" data-open-room-voice>Talk to Homely</button><button type="button" data-open-room-text>Type a thought</button><button type="button" data-edit-brief>Review brief</button></div>':''}${assistantOpen?`<div class="assistant-body"><div class="assistant-context">${state.project?'Working with '+esc(state.project.name)+' · saved version '+state.project.version:'Type or say a room to get started.'}${drafts[draftKey()]?' · Your brief has unsaved edits; the assistant uses the saved brief.':''}</div><div id="assistant-messages" class="assistant-messages" role="log" aria-label="Design conversation" aria-live="polite">${c.messages.map(m=>`<div class="assistant-message ${m.role}"><span>${m.role==='user'?'You':'Homely'}</span><p>${esc(m.text)}</p></div>`).join('')||'<p class="assistant-welcome">Try “Find six warm wood chairs” or “Compare the first two findings.” I’ll show proposed changes for you to review.</p>'}</div>${c.proposal?`<div class="assistant-proposal"><span class="tag lead">Proposed change · not applied</span><h3>Review before we change anything.</h3><p>${esc(c.proposal.summary)}</p><div class="candidate-actions"><button id="assistant-confirm" class="button primary" ${c.busy?'disabled':''}>Confirm this change</button><button id="assistant-cancel-proposal" class="button quiet" ${c.busy?'disabled':''}>Cancel proposal</button></div></div>`:''}<div class="assistant-error" role="alert" ${!c.error&&!voice.error?'hidden':''}>${esc(c.error||voice.error)}</div><form id="assistant-form"><label for="assistant-message">${voice.phase==='transcribing'?'Transcribing your recording…':'Your message / editable transcript'}</label><textarea id="assistant-message" name="message" maxlength="4000" rows="2" placeholder="${state.project?'Tell me what you have in mind…':'Or tell me about your room…'}" ${c.busy||recording?'disabled':''}>${esc(c.draft)}</textarea><div class="assistant-compose-actions"><button class="button primary" type="submit" ${c.busy||recording||c.proposal?'disabled':''}>${c.busy?'Working with your project…':!state.project?'Use this room':'Send to Homely'} ↗</button><button class="button quiet" id="voice-primer" type="button" ${c.busy||recording||c.proposal?'disabled':''} aria-label="Talk to Homely"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v3M9 21h6"/></svg></button></div></form><div class="voice-status" role="status" aria-live="polite">${voice.phase==='recording'?'● Recording · '+voice.seconds+'s / 60s':voice.phase==='requesting'?'Waiting for microphone permission…':voice.phase==='transcribing'?'Transcribing · no project action has been sent':voice.phase==='review'?'Transcript ready. Correct it above, then choose Send.':'Microphone off'}</div>${voice.phase==='recording'?'<div class="candidate-actions"><button class="button primary" id="voice-stop">Stop & review transcript</button><button class="button quiet" id="voice-cancel">Cancel recording</button></div>':['requesting','transcribing'].includes(voice.phase)?'<button class="button quiet" id="voice-cancel">Cancel voice input</button>':''}<div id="voice-consent" ${voice.phase==='consent'?'':'hidden'}><p>Your microphone is used only while recording. After Stop, audio is sent to the configured transcription provider. Review the text before sending a project action. Maximum 60 seconds or 8 MB.</p><label class="consent"><input id="voice-consent-checkbox" type="checkbox">I consent to recording and sending this audio for transcription.</label><div class="candidate-actions"><button class="button primary" id="voice-start">Start recording</button><button class="button quiet" id="voice-text-fallback">Keep typing</button></div></div>${!state.project?'<p class="room-first-hint">Choose a room above to send your thought with its project.</p>':''}<p class="assistant-footnote">Actual microphone/audio quality is not yet validated on this device. Typing is always available.</p></div>`:''}`;
$('#assistant-toggle').onclick=()=>{assistantOpen=!assistantOpen;if(!assistantOpen)cancelVoice(true);renderAssistant();};if(!assistantOpen){if($('[data-open-room-voice]'))$('[data-open-room-voice]').onclick=()=>{assistantOpen=true;voice.phase='consent';renderAssistant();};if($('[data-open-room-text]'))$('[data-open-room-text]').onclick=()=>{assistantOpen=true;renderAssistant();$('#assistant-message').focus();};return;}
$('#assistant-message').oninput=e=>{storeAssistantDraft(e.target.value);$('#assistant-panel').classList.toggle('has-draft',!!e.target.value.trim());};$('#assistant-panel').classList.toggle('has-draft',!!c.draft.trim());$('#assistant-form').onsubmit=e=>{e.preventDefault();submitAssistant();};$('#voice-primer').onclick=()=>{voice.phase='consent';voice.error='';renderAssistant();};$('#voice-start').onclick=()=>{if(!$('#voice-consent-checkbox').checked){voice.error='Please confirm audio consent, or keep typing.';renderAssistant();return;}startVoice();};$('#voice-text-fallback').onclick=()=>{cancelVoice(true);renderAssistant();$('#assistant-message').focus();};if($('#voice-cancel'))$('#voice-cancel').onclick=()=>{cancelVoice();renderAssistant();$('#assistant-message')?.focus();};if($('#voice-stop'))$('#voice-stop').onclick=stopVoice;if($('#assistant-confirm'))$('#assistant-confirm').onclick=()=>submitAssistant(true);if($('#assistant-cancel-proposal'))$('#assistant-cancel-proposal').onclick=()=>{c.proposal=null;c.error='';c.messages.push({role:'assistant',text:'Proposal cancelled. No change was applied.'});renderAssistant();};const log=$('#assistant-messages');log.scrollTop=log.scrollHeight;
}
async function submitAssistant(confirm=false){if(!state.project){const name=conversation().draft.trim();if(!name||name.length>100){notify('Tell us a room name in 100 characters or fewer.',true);return;}await chooseRoom(/dining/i.test(name)?'dining':/living/i.test(name)?'living':/bedroom/i.test(name)?'bedroom':'other',name);return;}const c=conversation(),projectId=state.project.id,requestScope=accountScope(),message=c.draft.trim();if(c.busy||(!confirm&&!message))return;if(!confirm&&c.proposal){c.error='Confirm or cancel the current proposal before sending another message.';renderAssistant();return;}const body=confirm?{confirmationId:c.proposal.id,expectedVersion:c.proposal.version}:{message,expectedVersion:state.project.version};c.busy=true;c.error='';if(!confirm)c.messages.push({role:'user',text:message});renderAssistant();try{const result=await api(`/api/projects/${encodeURIComponent(projectId)}/assistant`,'POST',body);c.messages.push({role:'assistant',text:result.reply||'The server returned no reply.'});if(result.confirmation){c.proposal={...result.confirmation,version:result.confirmation.expectedVersion??result.project?.version??body.expectedVersion};}else if(confirm)c.proposal=null;if(!confirm){c.draft='';try{sessionStorage.removeItem(scopedKey('assistantDraft.'+projectId));}catch{}}if(state.project?.id!==projectId||accountScope()!==requestScope)return;if(result.project){state.project=result.project;const i=state.projects.findIndex(p=>p.id===projectId);if(i>=0)state.projects[i]=result.project;}if(result.job){state.job=result.job;state.candidateFilter=null;state.view='findings';pollJob(result.job.id,'research',projectId);}render();if(result.command)applyAssistantCommand(result.command);}catch(e){c.error=e.status===409?'This project changed. The proposal was not applied. Review the latest saved project and ask again.':e.message;if(e.status===409){c.proposal=null;if(state.project?.id===projectId){await refreshProject().catch(()=>{});render();}}}finally{c.busy=false;if(state.project?.id===projectId)renderAssistant();}}
function applyAssistantCommand(command){const allowed=new Set((state.project?.candidates||[]).map(c=>c.id));const ids=(command.candidateIds||[]).filter(id=>allowed.has(id));if(command.type==='filter_candidates'){state.candidateFilter=ids;state.view='findings';render();}else if(command.type==='compare_candidates'){if(ids.length<2){conversation().error='The server did not identify two current candidates to compare.';return;}state.selected=new Set(ids);state.view='findings';render();compare();}else if(command.type==='request_visualization'){if(!allowed.has(command.candidateId)){conversation().error='The requested candidate is no longer in this project.';return;}visualize(command.candidateId);}}
function releaseMicrophone(){clearInterval(voice.timer);voice.timer=null;voice.stream?.getTracks().forEach(track=>track.stop());voice.stream=null;}
function cancelVoice(quiet=false){voice.token++;voice.abort?.abort();voice.abort=null;if(voice.recorder&&voice.recorder.state!=='inactive'){voice.recorder.onstop=null;voice.recorder.stop();}voice.recorder=null;releaseMicrophone();voice.phase='idle';voice.seconds=0;voice.error=quiet?'':'Voice input cancelled. Your typed draft is unchanged.';}
function stopVoice(){if(voice.recorder?.state==='recording'){voice.phase='transcribing';voice.recorder.stop();releaseMicrophone();renderAssistant();}}
async function startVoice(){cancelVoice(true);const token=++voice.token,projectId=state.project?.id;voice.phase='requesting';renderAssistant();try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Recording is not supported in this browser. Use the editable text field instead.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==voice.token||projectId!==state.project?.id){stream.getTracks().forEach(t=>t.stop());return;}voice.stream=stream;const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);voice.recorder=recorder;const chunks=[];let bytes=0;recorder.ondataavailable=e=>{if(token!==voice.token||!e.data.size)return;bytes+=e.data.size;if(bytes>8*1024*1024){cancelVoice(true);voice.error='Recording reached the 8 MB limit and was discarded. Try a shorter recording, or type your message.';renderAssistant();return;}chunks.push(e.data);};recorder.onerror=()=>{cancelVoice(true);voice.error='Audio recording failed. Your draft is intact; please type or retry.';renderAssistant();};recorder.onstop=async()=>{releaseMicrophone();if(token!==voice.token)return;voice.phase='transcribing';renderAssistant();try{const blob=new Blob(chunks,{type:recorder.mimeType||mime||'audio/webm'});if(!blob.size)throw new Error('No audio was captured. Please try again or type your message.');const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read the recording.'));reader.readAsDataURL(blob);});if(token!==voice.token)return;voice.abort=new AbortController();const response=await fetch('/api/transcriptions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl,consent:true}),signal:voice.abort.signal});const result=await response.json();if(!response.ok)throw new Error(typeof result.error==='string'?result.error:'Transcription failed. Please retry or type your message.');if(token!==voice.token||projectId!==state.project?.id)return;if(!result.text?.trim())throw new Error('No words were detected. Please retry or use text.');storeAssistantDraft(conversation().draft?(conversation().draft+'\n'+result.text.trim()):result.text.trim());voice.phase='review';voice.error='';renderAssistant();$('#assistant-message').focus();}catch(e){if(token!==voice.token)return;voice.phase='idle';voice.error=e.name==='AbortError'?'Transcription cancelled.':e.message;renderAssistant();}finally{if(token===voice.token)voice.abort=null;}};recorder.start(250);voice.phase='recording';voice.seconds=0;renderAssistant();voice.timer=setInterval(()=>{voice.seconds++;if(voice.seconds>=60)stopVoice();else {const el=$('.voice-status');if(el)el.textContent='● Recording · '+voice.seconds+'s / 60s';}},1000);}catch(e){if(token!==voice.token)return;releaseMicrophone();voice.phase='idle';voice.error=e.name==='NotAllowedError'?'Microphone permission was denied. You can keep typing, or allow microphone access in your browser and try again.':e.message;renderAssistant();}}
window.addEventListener('pagehide',()=>cancelVoice(true));$('#detail-dialog').addEventListener('close',()=>{const recovery=$('#recovery-form');if(recovery){recovery.reset();$('#detail-content').innerHTML='';}});
function journey(){const b=state.project?.brief||{};return {step:'intent',selectedCategories:b.itemType?[b.itemType]:[],retainedObjects:[],keepingDecision:null,...b.journey};}
async function saveJourney(patch,fields={}){return saveSetup({...fields,journey:{...journey(),...patch}});}
function journeyPhoto(){const url=state.project?.room?.imageUrl;return url?`<img src="${esc(safeUrl(url))}" alt="Your original room photo">`:'<div class="photo-empty">Your room photo is optional.<br>You can describe the pieces instead.</div>';}
function contextualCategories(){const key=selectedRoom()||'other',j=journey(),kept=j.retainedObjects.map(o=>o.label).join(' ');return roomOptions[key].categories.filter(([,item])=>!kept.toLowerCase().includes(item.toLowerCase())).slice(0,3).map(([label,item,art])=>({label,item,art,reason:/chair/i.test(item)&&/table/i.test(kept)?'To complement the table you’re keeping':/lighting/i.test(item)?'Explore light for this room':j.keepingDecision==='fresh'?'Start building your '+setupRoomLabel().toLowerCase():'Build around what you love'}));}
function workspaceView(){const key=selectedRoom(),j=journey(),b=state.project?.brief||{},step=key?j.step:'room';let content='';
if(step==='room')content=`<h2>Which room are we working on?</h2><p>Let’s start with the space you’re working on.</p><div class="room-choices">${['dining','living','bedroom'].map(k=>`<button class="room-choice" data-room-choice="${k}"><span class="reference-art art-${k}" aria-hidden="true"></span><span>${roomOptions[k].label}</span></button>`).join('')}</div><button class="other-room" data-other-room>Other room</button><form id="room-name-form" class="room-name-composer"><label for="room-name">Type or say a room</label><div><input id="room-name" name="room" maxlength="100" required placeholder="For example, home office"><button class="button primary">Continue →</button><button type="button" data-room-voice aria-label="Say a room">♩</button></div></form>`;
if(step==='intent')content=`<h2>How would you like to begin?</h2><p>Tell us how you’d like to get started.</p><div class="furnishing-choices"><button data-furnishing="keep" aria-label="Keep some furniture" aria-pressed="false"><svg class="intent-drawing" viewBox="0 0 150 100" aria-hidden="true"><path d="m20 29 22-10 95 7-19 12-98-9Zm0 0v8l98 9 19-12v-8M27 38l-3 48M111 45l4 47M47 42l-1 38M132 38l2 45M27 62l86 8"/></svg><strong>Keep some furniture</strong><small>Use pieces you already have and find the rest.</small></button><button data-furnishing="from_scratch" aria-label="Furnish from scratch" aria-pressed="false"><svg class="intent-drawing" viewBox="0 0 150 100" aria-hidden="true"><path d="M40 48V29Q40 12 58 12h35q19 0 19 17v20M43 68V46q-22-7-22 10v20q0 9 13 9h82q13 0 13-9V56q0-17-21-10v22M44 61q31-7 63 0v15H44V61ZM34 85l-2 10m83-10 3 10"/></svg><strong>Furnish from scratch</strong><small>Start with a clean slate and find everything new.</small></button></div><p class="field-hint">Tap to continue. You can go back.</p>`;
if(step==='photo')content=`<h2>Add your room photo <small>· optional</small></h2><p>A photo helps you show your space and what stays.</p><div class="journey-photo">${journeyPhoto()}</div><div class="journey-actions"><button class="button primary" data-journey-upload>Upload a photo</button><button class="button quiet" data-journey-camera>Take a photo</button><button class="button quiet" data-journey-next="measurements">${state.project.room?'Continue with this photo':'Skip for now'}</button></div>`;
if(step==='measurements')content=`<h2>A little about your space <small>· optional</small></h2><p>Add measurements now, or come back when you have a tape measure.</p><form id="room-measurements-form"><div class="field-row">${['width','depth','height'].map(k=>`<label>Room ${k}<input data-measurement type="number" name="${k}" min="0.1" step="any" value="${esc(j.roomMeasurements?.[k]??'')}" placeholder="Unknown"></label>`).join('')}<label>Units<select name="unit"><option value="in">Inches</option><option value="cm" ${j.roomMeasurements?.unit==='cm'?'selected':''}>Centimetres</option></select></label></div><button class="button primary">Save & continue</button><button type="button" class="button quiet" data-journey-next="${j.keepingDecision==='fresh'?'categories':'keep'}">Skip for now</button></form>`;
if(step==='keep')content=`<h2>Choose what stays <small>· optional</small></h2><p>Tap a piece in your photo, then tell us what it is.</p><div class="keep-layout"><div class="journey-photo anchor-photo" id="anchor-photo">${journeyPhoto()}${j.retainedObjects.filter(o=>o.anchor&&o.anchor.imageUrl===state.project.room?.imageUrl).map(o=>`<button class="photo-anchor" data-retained-edit="${esc(o.id)}" style="left:${o.anchor.x*100}%;top:${o.anchor.y*100}%" aria-label="Edit ${esc(o.label)}">✓</button>`).join('')}</div><div><p class="field-hint">Manual photo selection. Homely does not identify objects from this tap.</p><button class="button quiet" data-retained-text>Can’t select it? Tell us what to keep</button><div class="retained-list">${j.retainedObjects.map(o=>`<div><strong>${esc(o.label)}</strong><small>${esc(o.variant||'Exact variant not yet known')}</small><button data-retained-edit="${esc(o.id)}">Correct</button><button data-retained-undo="${esc(o.id)}">Undo</button></div>`).join('')}</div><button class="button primary" data-journey-next="categories">Continue</button><button class="button quiet" data-keep-later>Decide later</button></div></div>`;
if(step==='categories'||step==='preferences')content=`<h2>Personalize your search</h2><p>${j.keepingDecision==='fresh'?'Choose what to find for your room.':'Let’s build around what you’re keeping.'}</p><div class="category-choices">${contextualCategories().map(c=>`<button data-setup-category="${esc(c.item)}" aria-pressed="${j.selectedCategories.includes(c.item)}"><span class="reference-art category-${c.art}" aria-hidden="true"></span><strong>${esc(c.label)} ${j.selectedCategories.includes(c.item)?'✓':''}</strong><small>${esc(c.reason)}</small></button>`).join('')}</div><div class="journey-actions"><button class="button quiet" data-category-other>＋ Something else</button><button class="button quiet" data-help-decide>Help me decide</button></div>${j.selectedCategories.length?`<p>Looking for: ${j.selectedCategories.map(esc).join(', ')}</p>`:''}<button class="setup-budget" data-setup-budget><strong>Budget <small>· optional</small></strong><span>${b.flexibleTarget!=null?esc(money(b.flexibleTarget)):'Add budget'} ›</span></button><form id="journey-style-form"><label>Have a look in mind? <small>· optional</small><input name="style" maxlength="2000" value="${esc(b.style||'')}" placeholder="Describe a style, product or designer…"></label><button class="button primary full">Show options →</button></form>`;
if(step==='fit')content=fitJourneyView();
if(['results','saved'].includes(step))content=`<h2>Your room, coming together.</h2><p>Your preferences are saved. Check the measurements before viewing fit-qualified options.</p><div class="journey-actions"><button class="button primary" data-journey-next="fit">Check the fit</button><button class="button quiet" data-view="saved">Saved & alerts</button></div>`;
const steps={room:2,intent:3,photo:4,measurements:4,keep:5,categories:6,preferences:6,fit:7,results:8,saved:9};return `<section class="room-setup guided-room ${key?'make-yours':'choose-room'}"><div class="journey-progress"><span>${steps[step]||3} / 9</span><span>${key?esc(setupRoomLabel()):'A more personal home'} ${/^DEMO\b/i.test(state.project?.name||'')?'· DEMO / fictional project':''}</span>${key?'<button data-journey-back>← Back</button>':''}</div>${content}<div id="workspace-assistant-slot"></div>${key?`<div class="setup-utilities"><button data-edit-brief aria-label="Edit brief">Edit brief</button><button data-change-room>Change room</button><span>Progress saved as you go</span></div><details id="project-details" data-project-id="${esc(state.project.id)}" ${projectDetailsOpen.has(state.project.id)||drafts[draftKey()]||briefEditors.has(briefEditorKey())?'open':''}><summary>Room photo, brief & research</summary>${projectDetailsView().replace('<div id="workspace-assistant-slot"></div>','')}</details>`:''}</section>`;}
async function chooseRoom(key,label){const isNew=!state.project,oldDraft=conversation().draft;if(!state.project){const r=await api('/api/projects','POST',{name:label,mode:'pro'});state.project=r.project;state.projects.unshift(r.project);if(oldDraft)storeAssistantDraft(oldDraft);}state.chooseRoom=false;await saveSetup({roomType:key,roomLabel:label,journey:{...journey(),step:'intent',...(isNew?{selectedCategories:[]}: {})}});}
function retainedDialog(anchor,existing){const o=existing||{};$('#detail-content').innerHTML=`<h2>${existing?'Correct this piece':'What would you like to keep?'}</h2><p>${anchor?'You marked a point on your original photo. Confirm the object yourself.':'Describe the piece you want to keep.'}</p><form id="retained-form"><label>Piece name<input name="label" required maxlength="100" value="${esc(o.label||'')}" placeholder="e.g. My oak dining table"></label><label>Exact model / variant, if known<input name="variant" maxlength="200" value="${esc(o.variant||'')}" placeholder="Unknown is fine for now"></label><label class="consent"><input type="checkbox" name="confirmed" required ${o.confirmed?'checked':''}>I confirm this is the piece I’m keeping.</label><p class="field-hint">This confirms your description, not its dimensions or physical fit.</p><button class="button primary">Keep this piece</button></form>`;openDetail();$('#retained-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);action($('button',e.target),async()=>{const item={id:o.id||'retained-'+Date.now(),label:f.get('label').trim(),variant:f.get('variant').trim(),confirmed:true,...(anchor?{anchor}:o.anchor?{anchor:o.anchor}:{})};await saveJourney({retainedObjects:[...journey().retainedObjects.filter(x=>x.id!==item.id),item],keepingDecision:'keep'});$('#detail-dialog').close();});};}
function guidedCategory(){const cs=contextualCategories(),j=journey(),index=(j.categoryGuideIndex||0)>=cs.length?0:j.categoryGuideIndex||0,c=cs[index];if(!c){notify('Your choices are saved. Add a category or continue when ready.');return;}$('#detail-content').innerHTML=`<h2>Would ${esc(c.label.toLowerCase())} help?</h2><p>${esc(c.reason)}</p><div class="journey-actions"><button class="button primary" id="guide-yes">Yes</button><button class="button quiet" id="guide-no">Not now</button></div>`;openDetail();const answer=yes=>async e=>action(e.currentTarget,async()=>{await saveJourney({selectedCategories:yes?[...new Set([...journey().selectedCategories,c.item])]:journey().selectedCategories,categoryGuideIndex:index+1});$('#detail-dialog').close();if(index+1<cs.length)guidedCategory();});$('#guide-yes').onclick=answer(true);$('#guide-no').onclick=answer(false);}
function bindRoomSetup(){if($('[data-new-room]'))$('[data-new-room]').onclick=beginRoom;document.querySelectorAll('[data-room-choice]').forEach(b=>b.onclick=()=>action(b,()=>chooseRoom(b.dataset.roomChoice,roomOptions[b.dataset.roomChoice].label)));if($('#room-name-form'))$('#room-name-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('room').trim();if(!name)return;const key=/dining/i.test(name)?'dining':/living/i.test(name)?'living':/bedroom/i.test(name)?'bedroom':'other';action($('button',e.target),()=>chooseRoom(key,name));};if($('[data-room-voice]'))$('[data-room-voice]').onclick=()=>{voice.phase='consent';openAssistant();};document.querySelectorAll('[data-furnishing]').forEach(b=>b.onclick=()=>action(b,()=>saveJourney({step:'photo',keepingDecision:b.dataset.furnishing==='keep'?'keep':'fresh',...(b.dataset.furnishing==='from_scratch'?{retainedObjects:[]}: {})},{furnishingMode:b.dataset.furnishing})));document.querySelectorAll('[data-journey-next]').forEach(b=>b.onclick=()=>action(b,()=>saveJourney({step:b.dataset.journeyNext})));if($('[data-journey-back]'))$('[data-journey-back]').onclick=e=>action(e.currentTarget,()=>{const j=journey(),back={intent:'room',photo:'intent',measurements:'photo',keep:'measurements',categories:j.keepingDecision==='fresh'?'measurements':'keep',fit:'categories',results:'fit',saved:'results'};if(back[j.step]==='room'){state.chooseRoom=true;render();return;}return saveJourney({step:back[j.step]||'intent'});});document.querySelectorAll('[data-setup-category]').forEach(b=>b.onclick=()=>action(b,()=>{const j=journey(),item=b.dataset.setupCategory;return saveJourney({selectedCategories:j.selectedCategories.includes(item)?j.selectedCategories.filter(x=>x!==item):[...j.selectedCategories,item]});}));if($('[data-other-room]'))$('[data-other-room]').onclick=()=>setupDialog('other');if($('[data-setup-budget]'))$('[data-setup-budget]').onclick=()=>setupDialog('budget');if($('[data-change-room]'))$('[data-change-room]').onclick=()=>{state.chooseRoom=true;render();};if($('[data-help-decide]'))$('[data-help-decide]').onclick=guidedCategory;if($('[data-journey-upload]'))$('[data-journey-upload]').onclick=()=>journeyUpload(false);if($('[data-journey-camera]'))$('[data-journey-camera]').onclick=()=>journeyUpload(true);if($('#room-measurements-form'))$('#room-measurements-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),measure={unit:f.get('unit')};['width','depth','height'].forEach(k=>{if(f.get(k))measure[k]=Number(f.get(k));});action($('button',e.target),()=>saveJourney({roomMeasurements:measure,step:journey().keepingDecision==='fresh'?'categories':'keep'}));};if($('#anchor-photo img'))$('#anchor-photo').onclick=e=>{if(e.target.closest('button'))return;const img=$('#anchor-photo img'),r=img.getBoundingClientRect();retainedDialog({x:Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),y:Math.min(1,Math.max(0,(e.clientY-r.top)/r.height)),imageUrl:state.project.room.imageUrl});};if($('[data-retained-text]'))$('[data-retained-text]').onclick=()=>retainedDialog();document.querySelectorAll('[data-retained-edit]').forEach(b=>b.onclick=()=>retainedDialog(null,journey().retainedObjects.find(o=>o.id===b.dataset.retainedEdit)));document.querySelectorAll('[data-retained-undo]').forEach(b=>b.onclick=()=>action(b,()=>saveJourney({retainedObjects:journey().retainedObjects.filter(o=>o.id!==b.dataset.retainedUndo)})));if($('[data-keep-later]'))$('[data-keep-later]').onclick=e=>action(e.currentTarget,()=>saveJourney({keepingDecision:'later',step:'categories'}));if($('[data-category-other]'))$('[data-category-other]').onclick=()=>{$('#detail-content').innerHTML='<h2>What else would you like to find?</h2><form id="category-other-form"><label>Category<input name="category" required maxlength="100"></label><button class="button primary">Add category</button></form>';openDetail();$('#category-other-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('category').trim();action($('button',e.target),async()=>{await saveJourney({categoryOther:value,selectedCategories:[...new Set([...journey().selectedCategories,value])]});$('#detail-dialog').close();});};};if($('#journey-style-form'))$('#journey-style-form').onsubmit=e=>{e.preventDefault();const j=journey();if(!j.selectedCategories.length){notify('Choose a category, or use Help me decide.',true);return;}const style=new FormData(e.target).get('style').trim();action($('button',e.target),async()=>{await saveJourney({step:'fit'},{style,itemType:j.selectedCategories[0]});await loadFit();});};if($('#room-measurements-form'))bindMeasurementUnits($('#room-measurements-form'));bindFitJourney();bindWatch();}
function journeyUpload(camera){roomDialog();const form=$('#room-form');form.photo.removeAttribute('capture');if(camera)form.photo.setAttribute('capture','environment');const consent=form.querySelector('.consent');consent.innerHTML='<input type="checkbox" name="consent"><span>Allow this photo to be sent to the image provider only when I explicitly request an illustrative preview. Optional.</span>';const submit=form.onsubmit;form.onsubmit=async e=>{await submit(e);};}

const fitCache=new Map();
function currentFit(){return fitCache.get(accountScope()+':'+state.project?.id+':'+state.project?.version);}
async function loadFit(){if(!state.project)return;const key=accountScope()+':'+state.project.id+':'+state.project.version;if(fitCache.has(key))return;fitCache.set(key,{loading:true});try{const result=await api('/api/projects/'+state.project.id+'/fit');fitCache.set(key,result);}catch(e){fitCache.set(key,{error:e.message});}if(key===accountScope()+':'+state.project?.id+':'+state.project?.version)render();}
function fitJourneyDiagram(){return journey().keepingDecision==='fresh'?`<svg class="journey-fit-diagram" viewBox="0 0 600 215" role="img" aria-label="Measure the usable room width and depth for a rectangular furniture grid, and the maximum furniture height"><rect x="94" y="35" width="258" height="123" rx="3" fill="#e6eadd" stroke="#597765" stroke-width="2"/><g fill="#c7d7bf" stroke="#72906c" stroke-width="1.5"><rect x="117" y="55" width="92" height="34" rx="3"/><rect x="236" y="55" width="92" height="34" rx="3"/><rect x="117" y="105" width="92" height="34" rx="3"/><rect x="236" y="105" width="92" height="34" rx="3"/></g><g stroke="#1f6559" stroke-width="2" fill="none"><path d="M95 179h256m-247-6-9 6 9 6m238-12 9 6-9 6M73 36v122m-6-113 6-9 6 9m-12 104 6 9 6-9M471 42v115m-6-106 6-9 6 9m-12 97 6 9 6-9"/><path d="M411 159h147M421 42h137" stroke-dasharray="5 5"/></g><path d="M494 157V73h41v84" fill="#d9d1bb" stroke="#988b6c" stroke-width="2"/><text x="183" y="202">Room width</text><text x="17" y="86">Room</text><text x="17" y="104">depth</text><text x="407" y="20">Maximum furniture height</text><text x="172" y="23">Usable floor area</text><text x="409" y="193">Clearance limit</text></svg>`:`<svg class="journey-fit-diagram" viewBox="0 0 600 215" role="img" aria-label="Measure tabletop height, the lowest edge under the table, and space between the table legs"><rect x="140" y="36" width="320" height="15" fill="#bea882"/><path d="M160 51h280v22H160z" fill="#a68e6b"/><path d="M166 66v126M434 66v126" stroke="#a68e6b" stroke-width="11"/><path d="M80 37v153m-6-144 6-9 6 9m-12 135 6 9 6-9M275 75v115m-6-106 6-9 6 9m-12 97 6 9 6-9M182 147h236m-227-6-9 6 9 6m218-12 9 6-9 6" stroke="#1f6559" stroke-width="2" fill="none"/><text x="10" y="110">Tabletop</text><text x="10" y="127">height</text><text x="290" y="99">Lowest apron</text><text x="290" y="116">clearance</text><text x="205" y="174">Between table legs</text><path d="M30 195h520" stroke="#aaa"/></svg>`;}
function fitJourneyView(){const f=currentFit(),gate=f?.gate;queueMicrotask(loadFit);return `<h2>Check the fit</h2><p>A few confirmed measurements before fit-qualified recommendations.</p>${fitJourneyDiagram()}${quickFitForm()}<div class="truth-note">${f?.error?esc(f.error):f?.loading?'Checking saved evidence…':gate?.status==='passed'?'Your room evidence is complete. Each exact candidate still needs its own passing checks.':'Measurements or confirmations are still needed. Missing or conflicting evidence blocks fit-qualified results.'}</div>${gate?`<details><summary>${gate.checks?.filter(c=>c.status!=='passed').length||0} checks need attention · view evidence</summary>${humanFitEvidence(gate)}</details>`:''}<button class="button primary" data-edit-fit>Add or correct measurements</button>${journey().keepingDecision!=='fresh'?'<button class="button quiet" data-retained-product>Add your table’s product link · optional</button>':''}<p class="field-hint">Photo estimates are not measurements. Every fit statement is limited to the dimensional checks shown. Product availability is checked separately.</p><div class="journey-actions"><button class="button primary" data-fit-results ${gate?.status==='passed'?'':'disabled'}>View fit-qualified results</button><button class="button quiet" data-save-later>Save for later</button><button class="button quiet" data-browse-inspiration>Browse inspiration instead</button></div>`;}
function measurementInput(key,label,value){return `<label>${esc(label)}<input data-measurement name="${key}" type="number" min="0" step="any" value="${esc(value?.value??'')}" placeholder="Unknown"><select name="${key}Status" aria-label="${esc(label)} evidence status"><option value="confirmed">Ready to confirm</option><option value="unknown" ${value?.status==='unknown'?'selected':''}>Unknown</option><option value="conflicting" ${value?.status==='conflicting'?'selected':''}>Conflicting — needs resolution</option></select></label>`;}
function fitEditor(){const fit=state.project.brief.fit||{},fresh=journey().keepingDecision==='fresh',r=fit.retainedObject||{},dims=fresh?fit.room?.dimensions:r.dimensions, tol=fit.tolerances||{};const fields=fresh?[['width','Room width'],['depth','Room depth'],['heightLimit','Maximum furniture height']]:[['lowestApronHeight','Floor to lowest table edge / apron'],['tabletopHeight','Tabletop height']];const ts=fresh?[['chairGap','Gap between pieces'],['edgeClearance','Clearance at room edges']]:[['armClearance','Minimum arm-to-apron clearance'],['seatGapMin','Minimum seat-to-table gap'],['seatGapMax','Maximum seat-to-table gap'],['chairGap','Gap between adjacent chairs'],['edgeClearance','Clearance beside end chairs'],['pullOutClearance','Pull-out clearance behind chairs']];$('#detail-content').innerHTML=`<h2>${fresh?'Measure your planned layout':'Measure your retained table'}</h2><p>Enter your own measurements and explicit clearance tolerances. Leave uncertain values blank; conflicting evidence must be resolved before fit recommendations.</p><form id="fit-evidence-form"><label>Requested furniture quantity<input name="quantity" type="number" min="1" max="100" step="1" required value="${esc(state.project.brief.quantity||defaults.quantity)}"></label><label>Measurement source<select name="source"><option value="measured">I measured these values</option><option value="product_source" ${Object.values(dims||{})[0]?.source==='product_source'?'selected':''}>Exact product source</option></select></label><label>Source URL<input type="url" name="sourceUrl" value="${esc(Object.values(dims||{})[0]?.url||'')}" placeholder="Required for product-source dimensions"></label><p class="field-hint">Set uncertain or conflicting fields below. Values convert between inches and centimetres when you change units.</p><label>Units<select name="unit"><option value="in">Inches</option><option value="cm" ${Object.values(dims||{})[0]?.unit==='cm'?'selected':''}>Centimetres</option></select></label>${fresh?'':`<label>Retained table identity<input name="identity" maxlength="200" value="${esc(r.identity||journey().retainedObjects[0]?.label||'')}" placeholder="Your confirmed table"></label><label>Exact model / variant<input name="variant" maxlength="200" value="${esc(r.variant||journey().retainedObjects[0]?.variant||'')}" placeholder="Required for fit evidence"></label>`}<div class="field-row">${fields.map(([k,l])=>measurementInput(k,l,dims?.[k])).join('')}</div><h3>${fresh?'Grid arrangement':'Chairs on opposing sides'}</h3><p class="field-hint">${fresh?'One fixed orientation, rectangular floor layout.':'One or two parallel rows. Counts must total your requested quantity. End chairs and other arrangements need a different assessment.'}</p><div class="field-row">${fresh?`<label>Rows<input type="number" min="1" max="100" name="rows" value="${fit.arrangement?.rows||''}"></label><label>Columns<input type="number" min="1" max="100" name="columns" value="${fit.arrangement?.columns||''}"></label>`:[0,1].map(i=>`<label>Row ${i+1}: chair count<input name="count${i}" type="number" min="0" max="100" value="${fit.arrangement?.rows?.[i]?.count||''}"></label>${measurementInput('legSpacing'+i,'Row '+(i+1)+': usable space between legs',fit.arrangement?.rows?.[i]?.legSpacing)}${measurementInput('availableDepth'+i,'Row '+(i+1)+': available depth including pull-out',fit.arrangement?.rows?.[i]?.availableDepth)}`).join('')}</div><h3>Your required tolerances</h3><div class="field-row">${ts.map(([k,l])=>measurementInput(k,l,tol[k])).join('')}</div><label class="consent"><input name="confirmed" type="checkbox">I confirm the exact identity, measurements, arrangement and tolerances entered here.</label><button class="button primary">Save measurement evidence</button></form>`;openDetail();bindMeasurementUnits($('#fit-evidence-form'),{...dims,...tol,...Object.fromEntries([0,1].flatMap(i=>[['legSpacing'+i,fit.arrangement?.rows?.[i]?.legSpacing],['availableDepth'+i,fit.arrangement?.rows?.[i]?.availableDepth]]))});$('#fit-evidence-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),unit=f.get('unit'),confirmed=f.get('confirmed')==='on',E=k=>f.get(k)===''?undefined:{value:Number(f.get(k)),unit,source:f.get('source'),status:f.get(k+'Status')==='conflicting'?'conflicting':confirmed?f.get(k+'Status')||'confirmed':'unknown',...(f.get('source')==='product_source'?{url:f.get('sourceUrl')}: {})},build=keys=>Object.fromEntries(keys.map(k=>[k,E(k)]).filter(([,v])=>v!==undefined));const next={schemaVersion:1,scenario:fresh?'room_layout':'retained_dining_table',tolerances:{confirmed,...build(ts.map(([k])=>k))}};if(fresh){next.room={confirmed,dimensions:build(fields.map(([k])=>k))};next.arrangement={type:'grid',confirmed,...(f.get('rows')?{rows:Number(f.get('rows'))}:{}),...(f.get('columns')?{columns:Number(f.get('columns'))}:{})};}else{next.retainedObject={identity:f.get('identity').trim(),variant:f.get('variant').trim(),confirmed,dimensions:build(fields.map(([k])=>k))};next.arrangement={type:'parallel_rows',confirmed,rows:[0,1].filter(i=>Number(f.get('count'+i))>0).map(i=>({count:Number(f.get('count'+i)),...(E('legSpacing'+i)?{legSpacing:E('legSpacing'+i)}:{}),...(E('availableDepth'+i)?{availableDepth:E('availableDepth'+i)}:{})}))};}action($('button',e.target),async()=>{await saveSetup({fit:next,quantity:Number(f.get('quantity'))});$('#detail-dialog').close();await loadFit();});};}
function bindFitJourney(){bindQuickFit();if($('[data-retained-product]'))$('[data-retained-product]').onclick=retainedProductDialog;if($('[data-return-fit]'))$('[data-return-fit]').onclick=()=>{state.view='workspace';saveJourney({step:'fit'});};if($('[data-edit-fit]'))$('[data-edit-fit]').onclick=fitEditor;if($('[data-fit-results]'))$('[data-fit-results]').onclick=async()=>{await loadFit();if(currentFit()?.gate?.status!=='passed'){notify('Fit recommendations are blocked until missing or conflicting measurements are resolved.',true);return;}await saveJourney({resultMode:'fit'});state.findingMode='fit';state.view='findings';render();};if($('[data-save-later]'))$('[data-save-later]').onclick=()=>notify('Your progress is saved. Open this room to resume the fit check.');if($('[data-browse-inspiration]'))$('[data-browse-inspiration]').onclick=()=>{saveJourney({resultMode:'inspiration'}).then(()=>{state.findingMode='inspiration';state.view='findings';render();});};document.querySelectorAll('[data-candidate-fit]').forEach(b=>b.onclick=()=>candidateFitEditor(b.dataset.candidateFit));}
function candidateFitEditor(id){const c=getCandidate(id),fresh=journey().keepingDecision==='fresh';if(!c)return;const keys=fresh?['width','depth','height']:['armHeight','seatHeight','width','depth'];$('#detail-content').innerHTML=`<h2>Exact candidate fit evidence</h2>${currentFit()?.candidates?.find(a=>a.candidateId===id)?`<details><summary>Recorded checks & supporting evidence</summary>${humanFitEvidence(currentFit().candidates.find(a=>a.candidateId===id))}</details>`:''}<p>${esc(c.title)} · ${esc(c.exactSku||'SKU missing')} · ${esc(c.variant||'Variant missing')}</p><p>Confirm the dimensions for this exact SKU and variant. For an armless chair, explicitly enter arm height 0.</p><form id="candidate-fit-form"><p class="field-hint">Values convert between inches and centimetres when you change units.</p><label>Units<select name="unit"><option value="in">Inches</option><option value="cm" ${Object.values(c.fitEvidence?.dimensions||{})[0]?.unit==='cm'?'selected':''}>Centimetres</option></select></label><label>Source<select name="source"><option value="measured">I measured this exact item</option><option value="product_source" ${Object.values(c.fitEvidence?.dimensions||{})[0]?.source==='product_source'?'selected':''}>Exact product source</option></select></label><label>Source URL<input name="url" type="url" value="${esc(Object.values(c.fitEvidence?.dimensions||{})[0]?.url||'')}" placeholder="Required for a product source"></label>${keys.map(k=>measurementInput(k,k.replace(/([A-Z])/g,' $1'),c.fitEvidence?.dimensions?.[k])).join('')}<label class="consent"><input name="confirmed" type="checkbox" required>I confirm these dimensions describe this exact SKU and variant.</label><button class="button primary">Save candidate evidence</button></form>`;openDetail();bindMeasurementUnits($('#candidate-fit-form'),c.fitEvidence?.dimensions||{});$('#candidate-fit-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);action($('button',e.target),async()=>{const fitEvidence={exactSku:c.exactSku,variant:c.variant,dimensions:Object.fromEntries(keys.filter(k=>f.get(k)!=='').map(k=>[k,{value:Number(f.get(k)),unit:f.get('unit'),source:f.get('source'),status:f.get(k+'Status')||'confirmed',...(f.get('source')==='product_source'?{url:f.get('url')}: {})}]))};const result=await api('/api/projects/'+state.project.id+'/fit-evidence','POST',{expectedVersion:state.project.version,candidateId:id,fitEvidence});if(result.project)state.project=result.project;else await refreshProject();$('#detail-dialog').close();await loadFit();render();});};}

function renderAuthGate(){if($('#auth-form'))return;renderRail();$('#project-crumb').textContent='Private cloud workspace';$('#project-title').textContent='A more personal home.';$('#project-subtitle').textContent='Sign in to continue designing your home.';$('#view').innerHTML=`<section class="panel auth-panel journey-auth"><div><div class="eyebrow">YOUR PRIVATE SPACE</div><h2>Welcome back</h2><p>Sign in to continue designing your home.</p><form id="auth-form"><label>Email address<input aria-label="Email" type="email" name="email" autocomplete="email" required></label><label>Password<div class="password-row"><input aria-label="Password" type="password" name="password" autocomplete="current-password" required><button type="button" id="auth-show-password" aria-pressed="false">Show</button></div></label><div id="auth-message" role="status" aria-live="polite"></div><button class="button primary full" type="submit">Sign in</button><button class="button quiet full" type="button" id="auth-forgot">Forgot password?</button><button class="button quiet full" type="button" id="auth-sign-up">Create account</button><button class="button quiet full" type="button" id="auth-recovery-complete">Have a recovery email?</button><button class="button quiet" type="button" id="auth-resend" hidden>Resend confirmation email</button></form></div><div class="reference-art hero-dining" role="img" aria-label="Home inspiration"></div></section>`;const form=$('#auth-form');$('#auth-show-password').onclick=e=>{const show=form.password.type==='password';form.password.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-pressed',String(show));};const submit=async(signup)=>{if(form.dataset.busy==='true'||!form.reportValidity())return;form.dataset.busy='true';const f=new FormData(form),button=signup?$('#auth-sign-up'):$('button[type=submit]',form);setBusy(button,true,signup?'Creating account…':'Signing in…');$('#auth-message').textContent=signup?'Creating account…':'Signing in…';$('#auth-resend').hidden=true;try{const result=await api(signup?'/api/auth/sign-up':'/api/auth/sign-in','POST',{email:f.get('email').trim(),password:f.get('password')});form.password.value='';if(signup){$('#auth-message').textContent=result.message||'Check your email to confirm your account, then sign in.';$('#auth-resend').hidden=!(result.email_confirmation_required??result.confirmationRequired);return;}const auth=await api('/api/auth/session');if(!auth.authenticated)throw new Error('Sign-in did not create a session. Please retry.');resetAccountState(auth);await loadProjects();render();notify('Signed in to your private cloud workspace.');}catch(e){if($('#auth-message')){$('#auth-message').textContent=e.message;$('#auth-resend').hidden=!/email_not_confirmed|confirmation_required|unconfirmed/i.test(e.code||'')&&!/confirm your email|email.*not confirmed/i.test(e.message);}}finally{form.dataset.busy='false';if(form.isConnected)form.password.value='';setBusy(button,false);}};form.onsubmit=e=>{e.preventDefault();submit(false);};$('#auth-sign-up').onclick=()=>submit(true);const emailAction=path=>async e=>{if(form.dataset.busy==='true')return;const feature=path.endsWith('/recover')?'passwordRecovery':'confirmationResend';if(!state.availableFeatures?.[feature]){$('#auth-message').textContent=feature==='passwordRecovery'?'Password recovery is not connected in this preview. No recovery email has been sent.':'Confirmation resend is not connected in this preview. No email has been sent.';return;}if(!form.email.reportValidity())return;form.dataset.busy='true';setBusy(e.currentTarget,true,'Requesting…');try{const r=await api(path,'POST',{email:form.email.value.trim()});$('#auth-message').textContent=r.message||'If this address is eligible, check your email for the next steps.';}catch(err){$('#auth-message').textContent=err.message;}finally{form.dataset.busy='false';setBusy(e.currentTarget,false);}};$('#auth-recovery-complete').onclick=recoveryDialog;$('#auth-forgot').onclick=emailAction('/api/auth/recover');$('#auth-resend').onclick=emailAction('/api/auth/resend');}

function fitCheckLabel(id){const labels={'candidate.variant':'Candidate exact SKU and variant','candidate.armHeight':'Chair arm height','candidate.seatHeight':'Chair seat height','candidate.width':'Candidate width','candidate.depth':'Candidate depth','candidate.height':'Candidate height','arm.apron':'Chair arm / apron clearance','seat.minimumGap':'Minimum seat gap check','seat.maximumGap':'Maximum seat gap check',scenario:'Measurement plan',retainedObject:'Table identity & exact variant',category:'Supported furniture category',lowestApronHeight:'Lowest table edge / apron',tabletopHeight:'Tabletop height',armClearance:'Arm clearance tolerance',seatGapMin:'Minimum seat-to-table gap',seatGapMax:'Maximum seat-to-table gap',chairGap:'Gap between chairs',edgeClearance:'Edge clearance',pullOutClearance:'Chair pull-out clearance',quantity:'Requested quantity','arrangement.confirmed':'Confirmed arrangement','tolerances.confirmed':'Confirmed clearance tolerances','arrangement.type':'Chair arrangement','arrangement.count':'Chair count by row','arrangement.grid':'Furniture grid','room.confirmed':'Confirmed unobstructed room space','room.width':'Room width','room.depth':'Room depth','room.heightLimit':'Maximum furniture height','seatGap.range':'Seat-to-table gap range','table.geometry':'Table measurement consistency'};return labels[id]||(/^row\.\d+\./.test(id)?'Row '+(Number(id.split('.')[1])+1)+': '+(id.endsWith('legSpacing')?'space between legs':'available chair depth'):id.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[._]/g,' '));}
function humanFitEvidence(gate){return `<ul class="fit-check-list">${(gate.checks||[]).map(c=>`<li class="${c.status==='passed'?'checked':'missing'}"><strong>${c.status==='passed'?'✓':'○'} ${esc(fitCheckLabel(c.id))}</strong><span>${c.status==='passed'?(c.actualIn!=null?'Passed — '+c.actualIn+' in required; '+c.limitIn+' in allowed':'Confirmed'):c.status==='failed'?'Does not meet this constraint — '+esc(c.reason):c.evidence?.status==='conflicting'?'Conflicting evidence — resolve this measurement':c.evidence?.status==='unknown'?'Unknown — add and confirm a measurement':c.id==='category'?'This check currently supports dining chairs with a retained table.':c.reason?.includes('missing, conflicting')?'Add a measured value, units and source.':esc((c.reason||'Needs confirmation').replace(/\b(?:retainedObject|furnishingMode|schemaVersion)\b/g,'saved details'))}</span>${c.evidence?.value!=null?`<small>${esc(c.evidence.value)} ${esc(c.evidence.unit||'')} · ${c.evidence.source==='product_source'?'Product source':'Your measurement'}${safeUrl(c.evidence.url)?` · <a href="${esc(safeUrl(c.evidence.url))}" target="_blank" rel="noopener">View source</a>`:''}</small>`:''}</li>`).join('')||'<li>Add confirmed measurements to begin.</li>'}</ul>`;}
function retainedProductDialog(){const projectId=state.project.id,version=state.project.version;$('#detail-content').innerHTML='<h2>Add your table’s product link</h2><p>Review the exact model and source evidence before confirming. A product’s overall height is never substituted for apron clearance.</p><form id="retained-product-form"><label>Product page URL<input name="url" type="url" required></label><button class="button primary">Read product details</button></form><div id="retained-product-result"></div>';openDetail();$('#retained-product-form').onsubmit=e=>{e.preventDefault();const url=new FormData(e.target).get('url');action($('button',e.target),async()=>{const result=await api('/api/projects/'+projectId+'/retained-product','POST',{url,expectedVersion:version}),p=result.product||{};$('#retained-product-result').innerHTML=`<h3>${esc(p.title||'Product details')}</h3><p>SKU: ${esc(p.exactSku||'Unknown')} · Variant: ${esc(p.variant||'Unknown')}</p><p>Source: <a href="${esc(safeUrl(p.url)||safeUrl(url))}" target="_blank" rel="noopener">Product page</a></p><dl class="evidence-list">${Object.entries(p.dimensions||{}).map(([k,v])=>`<div><dt>${esc(fitCheckLabel(k))}</dt><dd>${esc(typeof v==='object'?v.value:v)} ${esc(typeof v==='object'?v.unit||'':'in')} · source observation, not confirmed</dd></div>`).join('')||'<p>No dimensions extracted. Measure the missing dimensions yourself.</p>'}</dl><p>Confirm or correct the identity and each measurement in the form. Extracted dimensions are not applied automatically.</p><button class="button primary" id="confirm-product-identity">Use these details for review</button>`;$('#confirm-product-identity').onclick=()=>{fitEditor();const form=$('#fit-evidence-form');form.elements.identity.value=p.title||'';form.elements.variant.value=p.variant||'';form.elements.source.value='product_source';form.elements.sourceUrl.value=p.url||url;form.elements.confirmed.checked=false;};});};}

function recoveryDialog(){if(!state.availableFeatures?.passwordRecovery){$('#auth-message').textContent='Password recovery is not connected in this preview.';return;}$('#detail-content').innerHTML=`<h2>Choose a new password</h2><p>Paste the recovery link from your Homely email. If you already opened it or it expired, request a new email.</p><form id="recovery-form" autocomplete="off"><label>Recovery email link or token hash<input name="recovery" type="text" required autocomplete="off" spellcheck="false" placeholder="Paste your recovery link"></label><label>New password<input aria-label="New password" name="newPassword" type="password" minlength="8" required autocomplete="new-password"></label><button class="button quiet" type="button" id="recovery-show-password" aria-pressed="false">Show password</button><p class="field-hint">The link is used only when you submit. It is never saved in browser storage.</p><div id="recovery-message" role="status"></div><button class="button primary" type="submit">Set new password</button></form>`;openDetail();const form=$('#recovery-form');$('#recovery-show-password').onclick=e=>{const show=form.newPassword.type==='password';form.newPassword.type=show?'text':'password';e.currentTarget.textContent=show?'Hide password':'Show password';e.currentTarget.setAttribute('aria-pressed',String(show));};form.onsubmit=e=>{e.preventDefault();if(form.dataset.busy==='true'||!form.reportValidity())return;let tokenHash=form.recovery.value.trim();try{if(tokenHash.startsWith('http')){const url=new URL(tokenHash);if(url.protocol!=='https:'||url.hostname!=='bbwmwwupvqajidqznsly.supabase.co'||url.pathname!=='/auth/v1/verify'||url.username||url.password||url.searchParams.get('type')!=='recovery')throw new Error('Use the password recovery link from your Homely email.');tokenHash=url.searchParams.get('token_hash')||url.searchParams.get('token')||'';}if(!/^[A-Za-z0-9_-]{20,2048}$/.test(tokenHash))throw new Error('Paste the complete Homely recovery link or token hash.');}catch(error){$('#recovery-message').textContent=error.message;return;}form.dataset.busy='true';const button=$('button[type=submit]',form);setBusy(button,true,'Updating password…');api('/api/auth/reset','POST',{tokenHash,newPassword:form.newPassword.value}).then(result=>{form.reset();$('#detail-dialog').close();$('#auth-message').textContent=result.message||'Password updated. Sign in with your new password.';}).catch(error=>{if($('#recovery-message'))$('#recovery-message').textContent=error.message;else notify(error.message,true);}).finally(()=>{form.newPassword.value='';form.dataset.busy='false';setBusy(button,false);});};}

function bindMeasurementUnits(form,records={}){if(!form?.elements.unit)return;const select=form.elements.unit;let prior=select.value;const convert=(input,from,to)=>{if(input.value===''||from===to)return;const value=Number(input.value);if(Number.isFinite(value))input.value=String(Math.round((from==='cm'?value/2.54:value*2.54)*1000000)/1000000);};form.querySelectorAll('input[data-measurement]').forEach(input=>{const record=records[input.name];if(record?.unit)convert(input,record.unit,prior);});select.onchange=()=>{const next=select.value;form.querySelectorAll('input[data-measurement]').forEach(input=>convert(input,prior,next));prior=next;};}
function quickFitForm(){const fit=state.project.brief.fit||{},fresh=journey().keepingDecision==='fresh',dimensions=fresh?fit.room?.dimensions:fit.retainedObject?.dimensions;return `<form id="fit-quick-form"><div class="fit-unit-row"><strong>${fresh?'Your usable space':'Your table measurements'}</strong><label>Units<select name="unit"><option value="in">in</option><option value="cm" ${Object.values(dimensions||{})[0]?.unit==='cm'?'selected':''}>cm</option></select></label></div>${(fresh?[['width','Room width'],['depth','Room depth'],['heightLimit','Maximum furniture height']]:[['lowestApronHeight','Under-table clearance'],['tabletopHeight','Tabletop height'],['legSpacing','Space between table legs']]).map(([k,l])=>`<label class="fit-quick-row">${l}<input data-measurement name="${k}" type="number" min="0.01" step="any" value="${esc((k==='legSpacing'?fit.arrangement?.rows?.[0]?.legSpacing:dimensions?.[k])?.value??'')}" placeholder="Unknown"></label>`).join('')}<label class="consent"><input type="checkbox" name="confirmed" required>I measured and confirm these entered values.</label><button class="button quiet" type="submit">Save these measurements</button><p class="field-hint">Exact identity, placement and clearance tolerances still need confirmation below.</p></form>`;}
function bindQuickFit(){const form=$('#fit-quick-form');if(!form)return;const fit=state.project.brief.fit||{},fresh=journey().keepingDecision==='fresh',dimensions=fresh?fit.room?.dimensions:fit.retainedObject?.dimensions;bindMeasurementUnits(form,{...dimensions,legSpacing:fit.arrangement?.rows?.[0]?.legSpacing});form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),E=k=>({value:Number(f.get(k)),unit:f.get('unit'),source:'measured',status:'confirmed'}),changes={};for(const k of fresh?['width','depth','heightLimit']:['lowestApronHeight','tabletopHeight'])if(f.get(k)!=='')changes[k]=E(k);const next={...fit,schemaVersion:1,scenario:fresh?'room_layout':'retained_dining_table'};if(fresh)next.room={...fit.room,dimensions:{...dimensions,...changes}};else{next.retainedObject={...fit.retainedObject,dimensions:{...dimensions,...changes}};if(f.get('legSpacing')!==''){const rows=fit.arrangement?.rows||[];next.arrangement={...fit.arrangement,type:'parallel_rows',rows:[{...rows[0],legSpacing:E('legSpacing')},...rows.slice(1)]};}}action($('button',form),async()=>{await saveSetup({fit:next});await loadFit();notify('Measured values saved. Review the remaining fit requirements.');});};}

function watchDate(value){return date(typeof value==='number'?value*1000:value);}
const watchCache=new Map();
async function loadWatches(force=false){const scope=accountScope();if(!force&&watchCache.has(scope))return;watchCache.set(scope,{loading:true});try{const result=await api('/api/watches');if(scope!==accountScope())return;watchCache.set(scope,result);}catch(e){if(scope!==accountScope())return;watchCache.set(scope,{error:e.message});}if(state.view==='saved'&&scope===accountScope())render();}
function watchPanel(){if(!state.availableFeatures?.priceWatch)return '<section class="panel watch-panel"><h3>Price watches</h3><p>Price watching is not connected in this preview. Saving does not enable alerts.</p></section>';const result=watchCache.get(accountScope());queueMicrotask(()=>loadWatches());if(!result||result.loading)return '<section class="panel watch-panel" role="status">Loading your watch preferences…</section>';if(result.error)return `<section class="panel watch-panel"><p>${esc(result.error)}</p><button class="button quiet" data-watch-retry>Retry watch status</button></section>`;const watches=result.watches||[],notifications=result.notifications||[];return `<section class="panel watch-panel"><h3>Your account’s price watches & updates</h3><p class="field-hint">${esc(result.deliveryNote||'Checks run while this local server is running. Updates appear here; email and push delivery are not connected.')}</p>${watches.map(w=>`<article class="watch-row"><strong>${esc(w.product?.title||w.title||w.candidateTitle||getCandidate(w.candidateId)?.title||'Saved item')}</strong><p>${esc(w.status||((w.enabled??w.active)?'Enabled':'Inactive'))} · Last check: ${esc(watchDate(w.lastCheckedAt||w.lastChecked))}</p>${w.nextCheckAt?`<p>Next check: ${esc(watchDate(w.nextCheckAt))}</p>`:''}${w.lastError||w.error?`<p role="status">${esc(w.lastError||w.error)}</p>`:''}${w.status!=='cancelled'&&w.enabled!==false?`<button class="button quiet" data-watch-cancel="${esc(w.id)}">Turn off watch</button>`:''}</article>`).join('')||'<p>No watches enabled for this account. Choose Watch price updates on a saved piece to opt in.</p>'}<div class="watch-notifications">${notifications.map(n=>`<article><strong>${esc(n.title||'Price update')}</strong><p>${esc(n.message||n.body||'An item’s recorded price changed. Open its source to review current evidence.')}</p><p>${n.previousPrice!=null&&n.currentPrice!=null?esc(money(n.previousPrice))+' → '+esc(money(n.currentPrice)):''}</p><small>${esc(watchDate(n.createdAt))}</small>${!n.readAt&&!n.read?`<button class="button quiet" data-notification-read="${esc(n.id)}">Mark as read</button>`:'<span>Read</span>'}</article>`).join('')}</div></section>`;}
function bindWatch(){document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>watchDialog(b.dataset.watch));if($('[data-watch-retry]'))$('[data-watch-retry]').onclick=()=>loadWatches(true);document.querySelectorAll('[data-watch-cancel]').forEach(b=>b.onclick=()=>action(b,async()=>{await api('/api/watches/'+encodeURIComponent(b.dataset.watchCancel)+'/cancel','POST',{});await loadWatches(true);notify('Watch turned off. Your saved piece remains.');}));document.querySelectorAll('[data-notification-read]').forEach(b=>b.onclick=()=>action(b,async()=>{await api('/api/notifications/'+encodeURIComponent(b.dataset.notificationRead)+'/read','POST',{});await loadWatches(true);}));}
function watchDialog(candidateId){const enabled=state.availableFeatures?.priceWatch;$('#detail-content').innerHTML=`<h2>Watch price updates for this item?</h2><p>Saving a piece does not turn on alerts. Enable a watch only if you want price checks for this exact item and variant.</p><p class="field-hint">${enabled?'Checks run while this local server is running. Updates appear in Saved; email and push notifications are not connected. You can turn the watch off any time.':'Price watching is not connected in this preview. Your saved selection is preserved; no alert or watch has been enabled.'}</p><button class="button primary" id="watch-enable" ${enabled?'':'disabled'}>Enable price watch</button><button class="button quiet" data-close>Not now</button>`;openDetail();$('#watch-enable').onclick=e=>action(e.currentTarget,async()=>{const scope=accountScope(),result=await api('/api/projects/'+state.project.id+'/watches','POST',{candidateId,enabled:true,expectedVersion:state.project.version});if(scope!==accountScope())return;watchCache.delete(scope);$('#detail-dialog').close();state.view='saved';render();notify(result.message||'Price watch enabled. Updates appear in Saved while this server is running.');});}

init();

// Keep the compact mobile disclosure usable when the same tab grows to desktop.
matchMedia('(min-width:951px)').addEventListener('change',event=>{
 const constraints=document.querySelector('.constraint-details');
 if(constraints)constraints.open=event.matches;
});
